window.__votdWeek && window.__votdWeek({"week":"2028-04-03","reading":"Enos–Words of Mormon","days":[{"d":"2028-04-03","ref":"Enos 1:9","b":"Enos","c":1,"v":9,"he":"וַיְהִי כַּאֲשֶׁר שָׁמַעְתִּי אֶת־הַדְּבָרִים הָאֵלֶּה וָאָחֵל לְהַרְגִּישׁ תְּשׁוּקָה לִשְׁלוֹם אַחַי הַנֶּפִיִּים עַל־כֵּן שָׁפַכְתִּי אֶת־כׇּל־נַפְשִׁי לֵאלֹהִים בַּעֲדָם׃","en":"Now, it came to pass that when I had heard these words I began to feel a desire for the welfare of my brethren, the Nephites; wherefore, I did pour out my whole soul unto God for them."},{"d":"2028-04-04","ref":"Enos 1:16","b":"Enos","c":1,"v":16,"he":"וַתְּהִי־לִי אֱמוּנָה וָאֶזְעַק אֶל־אֱלֹהִים כִּי יִשְׁמֹר אֶת־הַסְּפָרִים וַיִּכְרֹת עִמִּי בְּרִית כִּי יוֹצִיאֵם אֶל־הַלָּמָנִים בְּעִתּוֹ׃","en":"And I had faith, and I did cry unto God that he would preserve the records; and he covenanted with me that he would bring them forth unto the Lamanites in his own due time."},{"d":"2028-04-05","ref":"Jarom 1:6","b":"Jarom","c":1,"v":6,"he":"וַיָּפוֹצוּ עַל־פְּנֵי הָאָרֶץ הָרַבָּה וְגַם־הַלָּמָנִים וְהָיוּ רַבִּים מְאֹד מֵעַם הַנֶּפִיִּים וַיֶּאֱהֲבוּ רֶצַח וַיִּשְׁתּוּ דַּם חַיּוֹת׃","en":"And they were scattered upon much of the face of the land, and the Lamanites also. And they were exceedingly more numerous than were they of the Nephites; and they loved murder and would drink the blood of beasts."},{"d":"2028-04-06","ref":"Jarom 1:9","b":"Jarom","c":1,"v":9,"he":"וְכָכָה הָיִינוּ מוּכָנִים לִקְרַאת הַלָּמָנִים וְלֹא הִצְלִיחוּ נֶגְדֵּנוּ וַיָּקׇם דְּבַר־יְהוָה אֲשֶׁר־דִּבֶּר לַאֲבוֹתֵינוּ לֵאמֹר כַּאֲשֶׁר תִּשְׁמְרוּ אֶת־מִצְוֹתַי תַּצְלִיחוּ בָאָרֶץ׃","en":"And thus being prepared to meet the Lamanites, they did not prosper against us. But the word of the Lord was verified, which he spake unto our fathers, saying that: Inasmuch as ye will keep my commandments ye shall prosper in the land."},{"d":"2028-04-07","ref":"Omni 1:15","b":"Omni","c":1,"v":15,"he":"הִנֵּה יָדַע מוֹשִׁיָּה כִּי עַם זָרַהֶמְלָה יָצְאוּ מִירוּשָׁלַיִם בָּעֵת אֲשֶׁר צִדְקִיָּהוּ מֶלֶךְ יְהוּדָה הׇגְלָה בָּבֶלָה׃","en":"Behold, it came to pass that Mosiah discovered that the people of Zarahemla came out from Jerusalem at the time that Zedekiah, king of Judah, was carried away captive into Babylon."},{"d":"2028-04-08","ref":"Words of Mormon 1:5","b":"Words of Mormon","c":1,"v":5,"he":"לָכֵן בָּחַרְתִּי בַדְּבָרִים הָאֵלֶּה לְכַלּוֹת אֶת־כְּתָבַי עֲלֵיהֶם וְאֶת־יֶתֶר כְּתָבַי אֶקַּח מִלּוּחוֹת נֶפִי וְלֹא אוּכַל לִכְתֹּב אֶחָד מִמֵּאָה מִדִּבְרֵי עַמִּי׃","en":"Wherefore, I chose these things, to finish my record upon them, which remainder of my record I shall take from the plates of Nephi; and I cannot write the hundredth part of the things of my people."},{"d":"2028-04-09","ref":"Words of Mormon 1:8","b":"Words of Mormon","c":1,"v":8,"he":"וּתְפִלָּתִי לֵאלֹהִים הִיא בְּעַד אַחַי כִּי יָשׁוּבוּ פַּעַם אַחֶרֶת לָדַעַת אֶת־אֱלֹהִים אַף גְּאֻלַּת הַמָּשִׁיחַ כִּי יִהְיוּ עוֹד לְעַם נַחְמָד׃","en":"And my prayer to God is concerning my brethren, that they may once again come to the knowledge of God, yea, the redemption of Christ; that they may once again be a delightsome people."}]});
